  private effect1(): void {
    this.release1?.()
    const run = () => {
      this.box.value =
        this.plot.value === null ? this.box.value : measureBox(this.plot.value, this.box.value)
    }
    const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
    for (const element of [this.plot.value]) if (element) resize?.observe(element)
    this.release1 = () => {
      resize?.disconnect()
    }
    run()
  }

  private effect2(): void {
    this.reading.value.subscribe((now) => {
      this.position.value = now
    })
  }

